const params = tobub.params || {};
function normalizeUserId(input) {
  const value = String(input ?? "").trim();
  if (!value) throw new Error("uid 不能为空");
  if (/^https?:\/\//i.test(value)) {
    let parsed;
    try { parsed = new URL(value); } catch { throw new Error("uid 不是有效的抖音用户 ID 或主页 URL"); }
    if (!/(^|\.)douyin\.com$/i.test(parsed.hostname)) throw new Error("用户主页 URL 必须来自 douyin.com");
    const parts = parsed.pathname.split("/").filter(Boolean);
    const index = parts.indexOf("user");
    if (index < 0 || !parts[index + 1]) throw new Error("用户主页 URL 中没有有效的用户 ID");
    return decodeURIComponent(parts[index + 1]);
  }
  const clean = value.replace(/^@/, "");
  if (clean.length > 128 || /[/?#\s]/.test(clean)) throw new Error("uid 格式无效");
  return clean;
}
const uid = normalizeUserId(params.uid);
const count = Number(params.count ?? 10);
const maxScrollTimes = Number(params.maxScrollTimes ?? 20);
const saveResults = params.saveResults !== false;
if (!Number.isInteger(count) || count < 1 || count > 100) throw new Error("count 必须是 1 到 100 的整数");
if (!Number.isInteger(maxScrollTimes) || maxScrollTimes < 1 || maxScrollTimes > 100) throw new Error("maxScrollTimes 必须是 1 到 100 的整数");
const profileUrl = "https://www.douyin.com/user/" + encodeURIComponent(uid);
await tobub.adapter.navigate({ url: profileUrl, waitUntil: "domcontentloaded" });
await tobub.atoms.waitFor({ title: "的抖音", titleMatch: "contains" }, { timeout: 20_000 });
await tobub.adapter.dismissPopups();
const location = await tobub.adapter.getCurrentLocation();
const userDetails = await tobub.atoms.extractItem({ selector: "#user_detail_element", fields: [
  { name: "avatarUrl", selector: 'span[data-e2e="live-avatar"] img', source: "src" },
    { name: "avatarCandidates", selector: "img", source: "src", many: true },
  { name: "nickname", selector: 'div[data-e2e="user-info"] h1', source: "text" },
  { name: "followText", selector: '[data-e2e="user-info-follow"]', source: "text" },
  { name: "fansText", selector: '[data-e2e="user-info-fans"]', source: "text" },
  { name: "likeText", selector: '[data-e2e="user-info-like"]', source: "text" },
  { name: "douyinId", selector: 'span:has-text("抖音号：")', source: "text", transforms: [{ type: "match", pattern: { pattern: "抖音号：(.+)" } }] },
  { name: "ipLocation", selector: 'span:has-text("IP属地：")', source: "text", transforms: [{ type: "match", pattern: { pattern: "IP属地：(.+)" } }] },
  { name: "remark", selector: 'div[data-e2e="user-info"] > div:last-child', source: "text" }
] });
const avatarCandidates = Array.isArray(userDetails.avatarCandidates) ? userDetails.avatarCandidates.filter((value) => typeof value === "string" && /^https?:\/\//i.test(value)) : [];
if (!userDetails.avatarUrl) userDetails.avatarUrl = avatarCandidates.find((value) => /avatar/i.test(value)) ?? avatarCandidates[0] ?? null;
delete userDetails.avatarCandidates;
const postCountRaw = await tobub.atoms.extractItem({ selector: "div#user-tabbar", fields: [{ name: "count", selector: 'span[data-e2e="user-tab-count"]', source: "textContent" }] });
const postCountText = String(postCountRaw?.count ?? "").trim();
const postCountMatch = postCountText.match(/([\d.]+)\s*(万|亿)?/);
const postCount = postCountMatch ? Math.round(Number(postCountMatch[1]) * (postCountMatch[2] === "亿" ? 100_000_000 : postCountMatch[2] === "万" ? 10_000 : 1)) : null;
const userUrl = location.url || profileUrl;
let userContent = null;
if (saveResults) {
  userContent = await tobub.db.saveContent({ platform: "douyin", contentType: "user", externalId: uid, title: userDetails.nickname ?? uid, summary: userDetails.remark ?? "", url: userUrl, metadata: { ...userDetails, uid, postCount, postCountText }, rawData: userDetails });
}
await tobub.atoms.waitFor([1000, 2000]);
const records = [];
const seen = new Set();
let scans = 0;
let savedCount = 0;
let noProgressScans = 0;
let stopReason = "maxScrollTimes";
for (let i = 0; i < maxScrollTimes && records.length < count; i++) {
  scans++;
  const postList = await tobub.adapter.extract("post_list", { scan: { mode: "append" } });
  let added = 0;
  for (const record of postList?.records ?? []) {
    if (records.length >= count) break;
    const fields = record.fields ?? {};
    const externalId = String(record.id || fields.id || "");
    if (!externalId || seen.has(externalId)) continue;
    seen.add(externalId);
    records.push(record);
    added++;
    if (saveResults) {
      await tobub.db.saveContent({
        platform: "douyin",
        contentType: "video",
        externalId,
        parentId: userContent?.contentItemId,
        title: fields.intro ?? "抖音视频 " + externalId,
        summary: fields.status ?? "",
        url: "https://www.douyin.com/video/" + externalId,
        metadata: { image: fields.image ?? "", status: fields.status ?? "", comments: fields.comments ?? "0", authorUid: uid },
        rawData: fields
      });
      savedCount++;
    }
  }
  noProgressScans = added === 0 ? noProgressScans + 1 : 0;
  if (records.length >= count) { stopReason = "requested_count"; break; }
  const endState = await tobub.atoms.condition({ type: "text", selector: "body", text: "暂时没有更多了", throwOnTimeout: false }, { timeout: 350 });
  if (endState.satisfied) { stopReason = "end_of_list"; break; }
  if (noProgressScans >= 3) { stopReason = records.length === 0 ? "no_posts" : "no_progress"; break; }
  if (i + 1 < maxScrollTimes) {
    await tobub.atoms.scroll({ mode: "viewport", distance: tobub.utils.randInt(500, 1100), steps: tobub.utils.randInt(4, 10), stepPauseRange: [20, 50] });
    await tobub.atoms.waitFor([700, 1600]);
  }
}
return { user: { ...userDetails, uid, postCount, postCountText, url: userUrl }, records, savedCount, scans, complete: records.length >= count || stopReason === "end_of_list", stopReason };
